"""Criteria for the two hardware rules.

Each criterion checks “which line, which rule,” not the full message text—the message can change, while line number and
rule name are the contract.
"""

from pathlib import Path

from _checks import hardware
from _checks.paths import EXAMPLES_ROOT

PREAMBLE = (
    "import pypto_pro.language as pl\nfrom pypto_pro.language import Vf as vf\n\n\n"
)


def _write(tmp_path: Path, body: str, *, docstring: str = "") -> Path:
    doc = f'    """{docstring}\n    """\n' if docstring else ""
    text = PREAMBLE + "@pl.vector_function\ndef _body(src, dst):\n" + doc + body
    path = tmp_path / "kernel.py"
    path.write_text(text, encoding="utf-8")
    return path


BODY = 7
"""Line number of the first function-body line in files generated by `_write` (two import lines + two blank lines +
decorator + def).
The criterion is expressed as `BODY + k` instead of a literal: miscounting blank lines caused every test to fail the
first time I wrote this suite."""


def _hits(path: Path) -> list[tuple[int, str, bool]]:
    return [
        (finding.lineno, finding.rule, finding.waived)
        for finding in hardware.check(path)
    ]


# ---------------------------------------------------------------------------
# squeeze-alternation
# ---------------------------------------------------------------------------


def test_the_compliant_chain_passes(tmp_path):
    path = _write(
        tmp_path,
        "    vf.clear_spr()\n"
        "    areg = vf.unalign_reg_for_store()\n"
        "    a = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n"
        "    vf.squeeze_store_unalign(dst, a, areg)\n"
        "    b = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n"
        "    vf.squeeze_store_unalign(dst, b, areg)\n"
        "    vf.squeeze_store_unalign_post(dst, areg)\n",
    )
    assert _hits(path) == []


def test_two_squeezes_in_a_row_are_reported(tmp_path):
    """Official `squeeze_store_unalign.md:43`: failure to alternate **may hang the hardware**. Parsing does not block it
    at all.
    """
    path = _write(
        tmp_path,
        "    vf.clear_spr()\n"
        "    a = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n"
        "    b = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n"
        "    vf.squeeze_store_unalign(dst, a, areg)\n"
        "    vf.squeeze_store_unalign(dst, b, areg)\n",
    )
    assert _hits(path) == [
        (BODY + 2, hardware.ALTERNATION, False),
        (BODY + 4, hardware.ALTERNATION, False),
    ]


def test_a_store_with_nothing_pending_is_reported(tmp_path):
    path = _write(tmp_path, "    vf.squeeze_store_unalign(dst, a, areg)\n")
    assert _hits(path) == [(BODY, hardware.ALTERNATION, False)]


def test_a_squeeze_nobody_consumes_is_reported(tmp_path):
    path = _write(
        tmp_path,
        "    vf.clear_spr()\n"
        "    a = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n",
    )
    assert _hits(path) == [(BODY + 1, hardware.ALTERNATION, False)]


def test_no_store_reg_does_not_touch_ar(tmp_path):
    """`NO_STORE_REG` does not write AR and does not need `clear_spr`; neither rule should flag it."""
    path = _write(
        tmp_path,
        "    a = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.NO_STORE_REG)\n",
    )
    assert _hits(path) == []


def test_a_gather_mode_that_is_not_a_literal_is_reported_not_guessed(tmp_path):
    """The admission rule in `references/tooling/checks.md` is “report unknowns as unknown”: state when a case cannot be
    judged instead of granting a free pass.
    """
    path = _write(
        tmp_path, "    vf.clear_spr()\n    a = vf.squeeze(src, m, gather_mode=chosen)\n"
    )
    hits = _hits(path)
    assert [(lineno, rule) for lineno, rule, _ in hits] == [
        (BODY + 1, hardware.ALTERNATION)
    ]
    assert "判不了" in hardware.check(path)[0].message


def test_a_nested_call_is_reported_because_source_order_is_not_evaluation_order(
    tmp_path,
):
    path = _write(
        tmp_path,
        "    vf.clear_spr()\n"
        "    vf.squeeze_store_unalign("
        "dst, vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG), areg)\n",
    )
    hits = _hits(path)
    assert [(lineno, rule) for lineno, rule, _ in hits] == [
        (BODY + 1, hardware.ALTERNATION)
    ]
    assert "求值顺序" in hardware.check(path)[0].message


def test_a_loop_body_must_balance_on_its_own(tmp_path):
    """There is only one AR: if a loop body squeezes without consuming the value, the next iteration reads the preceding
    iteration's byte count.
    """
    path = _write(
        tmp_path,
        "    vf.clear_spr()\n"
        "    for i in pl.range(4):\n"
        "        a = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n",
    )
    assert _hits(path) == [(BODY + 2, hardware.ALTERNATION, False)]


def test_a_balanced_loop_body_passes(tmp_path):
    path = _write(
        tmp_path,
        "    vf.clear_spr()\n"
        "    for i in pl.range(4):\n"
        "        a = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n"
        "        vf.squeeze_store_unalign(dst, a, areg)\n",
    )
    assert _hits(path) == []


def test_a_squeeze_outside_a_loop_that_stores_inside_is_reported(tmp_path):
    """A linear scan would miss this form: one squeeze, then consumption on every loop iteration reads stale data
    starting with the second iteration.
    """
    path = _write(
        tmp_path,
        "    vf.clear_spr()\n"
        "    a = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n"
        "    for i in pl.range(4):\n"
        "        vf.squeeze_store_unalign(dst, a, areg)\n",
    )
    assert _hits(path) == [(BODY + 2, hardware.ALTERNATION, False)]


def test_a_branch_is_reported_rather_than_linearised(tmp_path):
    path = _write(
        tmp_path,
        "    vf.clear_spr()\n"
        "    if flag:\n"
        "        a = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n"
        "        vf.squeeze_store_unalign(dst, a, areg)\n",
    )
    hits = _hits(path)
    assert [(lineno, rule) for lineno, rule, _ in hits] == [
        (BODY + 1, hardware.ALTERNATION)
    ]
    assert "分支顺序不唯一" in hardware.check(path)[0].message


