# ---------------------------------------------------------------------------
# Counterexample declaration cases
# ---------------------------------------------------------------------------


def test_a_declared_counterexample_is_waived_but_still_printed(tmp_path):
    path = _write(
        tmp_path,
        "    vf.clear_spr()\n"
        "    a = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n"
        "    b = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n",
        docstring="反例：squeeze-alternation —— 这一例的内容就是这条违规",
    )
    hits = _hits(path)
    assert [waived for _, _, waived in hits] == [True, True]
    assert "这一例的内容就是这条违规" in str(hardware.check(path)[0])


def test_the_declaration_may_be_indented(tmp_path):
    """Docstrings are indented; forcing the declaration to column zero would make examples ugly. The declaration in
    `vf_unalign` is indented.
    """
    path = _write(
        tmp_path,
        "    vf.clear_spr()\n"
        "    a = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n"
        "    b = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n",
        docstring="第一行是别的话。\n\n    反例：squeeze-alternation —— 缩进的声明也算",
    )
    assert [waived for _, _, waived in _hits(path)] == [True, True]


def test_a_declaration_with_nothing_to_waive_is_an_error(tmp_path):
    """Waivers can go stale. If a counterexample becomes compliant but its declaration remains, it can hide a real
    future violation.
    """
    path = _write(
        tmp_path,
        "    vf.clear_spr()\n"
        "    a = vf.squeeze(src, m, gather_mode=pl.SqueezeMode.STORE_REG)\n"
        "    vf.squeeze_store_unalign(dst, a, areg)\n",
        docstring="反例：squeeze-alternation —— 已经改回合规写法了",
    )
    findings = hardware.check(path)
    assert [(finding.rule, finding.waived) for finding in findings] == [
        (hardware.ALTERNATION, False)
    ]
    assert "豁免失效" in findings[0].message


def test_repo_waivers_are_limited_to_documented_probes(tmp_path):
    """Only the unalign counterexample and single-squeeze AR observation are waived."""
    findings = [
        finding
        for path in sorted((EXAMPLES_ROOT / "basic_api").rglob("*.py"))
        for finding in hardware.check(path)
    ]
    assert all(finding.waived for finding in findings), [str(f) for f in findings]
    owners = {finding.path.parent.name for finding in findings}
    assert owners == {"vf_unalign", "spr_ctrl"}


# ---------------------------------------------------------------------------
# unalign-reg-budget
# ---------------------------------------------------------------------------


def _uregs(count, *, disjoint=False):
    """Create `count` `unalign_reg_for_store` values; in the disjoint form, consume each immediately after
    declaration."""
    lines = []
    for i in range(count):
        lines.append(f"    a{i} = vf.unalign_reg_for_store()\n")
        if disjoint:
            lines.append(f"    vf.store_unalign(dst, reg, a{i}, 4, post_update=True)\n")
    if not disjoint:
        lines += [
            f"    vf.store_unalign(dst, reg, a{i}, 4, post_update=True)\n"
            for i in range(count)
        ]
    return "".join(lines)


def test_four_live_unalign_registers_are_fine(tmp_path):
    assert _hits(_write(tmp_path, _uregs(4))) == []


def test_five_live_unalign_registers_are_reported(tmp_path):
    """Measurement found that five values live for the whole function make bisheng segfault in the Greedy Register
    Allocator, with no diagnostic.
    """
    findings = hardware.check(_write(tmp_path, _uregs(5)))
    assert [finding.rule for finding in findings] == [hardware.UNALIGN_BUDGET]
    assert "5 个" in findings[0].message and "segfault" in findings[0].message


def test_five_with_disjoint_lifetimes_is_not_reported(tmp_path):
    """**This test prevents overblocking.** Measurement showed this form runs; a rule that counts declarations would
    falsely reject it.

    Keep the principle in mind: an overly broad conservative limit can reject a correct kernel.
    """
    assert _hits(_write(tmp_path, _uregs(5, disjoint=True))) == []


def test_an_interleaved_plain_load_does_not_count_against_the_budget(tmp_path):
    """`vf.load` also declares an UnalignReg internally, but consumes it immediately; measurement showed that four live
    values plus one load still run.
    """
    body = (
        "    a0 = vf.unalign_reg_for_store()\n"
        "    a1 = vf.unalign_reg_for_store()\n"
        "    a2 = vf.unalign_reg_for_store()\n"
        "    a3 = vf.unalign_reg_for_store()\n"
        "    extra = vf.load(src)\n"
        "    vf.store_unalign(dst, extra, a0, 4, post_update=True)\n"
        "    vf.store_unalign(dst, extra, a1, 4, post_update=True)\n"
        "    vf.store_unalign(dst, extra, a2, 4, post_update=True)\n"
        "    vf.store_unalign(dst, extra, a3, 4, post_update=True)\n"
    )
    assert _hits(_write(tmp_path, body)) == []


def test_omitted_squeeze_mode_writes_ar_on_a5(tmp_path):
    path = _write(tmp_path, "    vf.clear_spr()\n    a = vf.squeeze(src, m)\n")
    assert _hits(path) == [(BODY + 1, hardware.ALTERNATION, False)]


def test_explicit_none_mode_is_not_assumed_to_disable_ar(tmp_path):
    path = _write(
        tmp_path, "    vf.clear_spr()\n    a = vf.squeeze(src, m, gather_mode=None)\n"
    )
    assert "判不了" in hardware.check(path)[0].message
